    public function afterAnalysis(AfterAnalysisContext $context): void
    {
        $coverage = TypeCoverage::parameters($context);
        if ($coverage->total === 0 || $coverage->percentage() >= $this->required) {
            return;
        }

        $message = sprintf(
            'Out of %d possible param types, only %d - %.1f %% actually have it. Add more param types to get over %s %%',
